import { z } from 'zod';

/**
 * Customer order-tracking contracts.
 *
 * They live in their own module (and their own entry point) so the apps that
 * do not use the feature do not carry them: the web app only needs them in
 * the lazy chunks that render the tracking page and the order-card panel.
 */

/**
 * A tracking link is an opaque, unguessable token that lets a customer see
 * one order's progress without an account. The token is generated by the
 * server and never contains business or customer data, so a leaked link
 * cannot be enumerated.
 */
export const orderTrackingTokenSchema = z.string()
  .trim()
  .regex(/^[A-Za-z0-9_-]{32,64}$/, 'A tracking token is 32-64 URL-safe characters');

export const customerMessageKinds = ['FITTING_CONFIRMED', 'QUESTION', 'CHANGE_REQUESTED'] as const;
export const customerMessageKindSchema = z.enum(customerMessageKinds);
export type CustomerMessageKind = (typeof customerMessageKinds)[number];

export const customerMessageStatuses = ['OPEN', 'RESOLVED'] as const;
export const customerMessageStatusSchema = z.enum(customerMessageStatuses);
export type CustomerMessageStatus = (typeof customerMessageStatuses)[number];

/** What a customer can send back through a tracking link. */
export const customerMessageInputSchema = z.object({
  kind: customerMessageKindSchema,
  body: z.string().trim().max(1000).optional(),
}).strict();
